import{_ as n,C as E,o as t,c as d,a5 as r,b as i,w as a,a as o,E as c,a7 as l}from"./chunks/framework.QWVCgkrI.js";const T=JSON.parse('{"title":"Gitのrebase — コミットの再適用と履歴の書き換え","description":"","frontmatter":{"title":"Gitのrebase — コミットの再適用と履歴の書き換え","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"ゲーム設定の同じ分岐をmergeとrebaseで統合し、同じtreeを指すコミットが異なる親とIDを持つ理由と、共有済み履歴への影響を読む。","aliases":["Git rebase","リベース","コミットの再適用","履歴の書き換え","rebaseとmerge"],"verification":"Git公式のrebase・commit-treeとPro Gitに照合し、Windowsの独立リポジトリで再適用後の親・tree・旧履歴との関係を確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-rebase.md","filePath":"tools/git-rebase.md"}'),b={name:"tools/git-rebase.md"};function m(h,e,g,p,B,A){const s=E("Mermaid");return t(),d("div",null,[e[2]||(e[2]=r('<h1 id="gitのrebase-—-コミットの再適用と履歴の書き換え" tabindex="-1">Gitのrebase — コミットの再適用と履歴の書き換え <a class="header-anchor" href="#gitのrebase-—-コミットの再適用と履歴の書き換え" aria-label="Permalink to &quot;Gitのrebase — コミットの再適用と履歴の書き換え&quot;">​</a></h1><p>ゲームの <code>stage.txt</code> を更新する間に、別のブランチで敵のHPと出現数を変更したとします。これらの変更はmergeでもrebaseでも取り込めます。この例では、出来上がるファイルは同じでも、どのコミットを親としてたどれるかが変わります。<a href="https://git-scm.com/book/en/v2/Git-Branching-Rebasing#_rebasing" target="_blank" rel="noreferrer">Pro Gitのrebaseの解説</a></p><h2 id="rebaseは新しい基準の上で変更を再適用する" tabindex="-1">rebaseは新しい基準の上で変更を再適用する <a class="header-anchor" href="#rebaseは新しい基準の上で変更を再適用する" aria-label="Permalink to &quot;rebaseは新しい基準の上で変更を再適用する&quot;">​</a></h2><p>共通のコミットBから、<code>main</code> ではUでステージ番号を <code>2</code> に変えました。<code>topic</code> ではT1で敵のHPを <code>20</code> に変え、T2で出現数 <code>3</code> の <code>spawn.txt</code> を追加しました。図の矢印は親から子へ向いています。mergeとrebaseは元の分岐から別々に実行した結果です。</p>',4)),(t(),i(l,null,{default:a(()=>[c(s,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20%E5%90%8C%E3%81%98%E5%88%86%E5%B2%90%E3%82%92merge%E3%81%A8rebase%E3%81%A7%E7%B5%B1%E5%90%88%E3%81%97%E3%81%9F%E5%B1%A5%E6%AD%B4%0A%20%20%20%20accDescr%3A%20B%E3%81%8B%E3%82%89main%E3%81%AEU%E3%81%A8topic%E3%81%AET1%E3%83%BBT2%E3%81%B8%E5%88%86%E5%B2%90%E3%81%99%E3%82%8B%E3%80%82M%E3%81%AFU%E3%81%A8T2%E3%82%92%E8%A6%AA%E3%81%AB%E6%8C%81%E3%81%A4%E3%80%82rebase%E3%81%A7%E3%81%AFU%E3%81%8B%E3%82%89T1'%E3%80%81T2'%E3%81%B8%E9%80%B2%E3%82%80%E3%80%82%0A%20%20%20%20base%5B%22B%20%E5%85%B1%E9%80%9A%E3%81%AE%E5%9F%BA%E6%BA%96%22%5D%20--%3E%20upstream%5B%22U%20main%22%5D%0A%20%20%20%20base%20--%3E%20t1%5B%22T1%20HP%E5%A4%89%E6%9B%B4%22%5D%20--%3E%20t2%5B%22T2%20%E5%87%BA%E7%8F%BE%E6%95%B0%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20%20%20upstream%20--%3E%20merged%5B%22M%20merge%22%5D%0A%20%20%20%20t2%20--%3E%20merged%0A%20%20%20%20upstream%20--%3E%20r1%5B%22T1%E2%80%B2%20HP%E5%A4%89%E6%9B%B4%22%5D%20--%3E%20r2%5B%22T2%E2%80%B2%20%E5%87%BA%E7%8F%BE%E6%95%B0%E8%BF%BD%E5%8A%A0%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r(`<p>mergeではUとT2の変更を統合し、二つを親とするMを作ります。rebaseではT1の変更をUの状態に再適用してT1′を作り、続いてT2の変更をT1′の状態に再適用してT2′を作ります。検証では、Uから作った <code>merged</code> をmergeで、T2から作った <code>rebased</code> をrebaseで更新しました。<a href="/study/tools/git-three-way-merge.html">Gitの3-way merge</a> · <a href="https://git-scm.com/docs/git-rebase/2.39.0#_description" target="_blank" rel="noreferrer">Git 2.39のrebaseマニュアル</a></p><h2 id="新しい親によってコミットidが変わる" tabindex="-1">新しい親によってコミットIDが変わる <a class="header-anchor" href="#新しい親によってコミットidが変わる" aria-label="Permalink to &quot;新しい親によってコミットIDが変わる&quot;">​</a></h2><p>コミットオブジェクトには、スナップショットを指すルートtreeと親コミットのIDの両方があります。元のT1の親はBですが、T1′の親はUです。変更の意図やメッセージが同じでも、親のIDが変わるとコミットオブジェクトの内容が変わります。その内容に基づいてIDを計算するため、この例ではT1′に別のIDが付き、T2′も新しい親T1′を参照します。<a href="/study/tools/git-objects.html">Gitの保存モデル</a> · <a href="https://git-scm.com/book/en/v2/Git-Internals-Git-Objects#_git_commit_objects" target="_blank" rel="noreferrer">Pro Gitのコミットオブジェクト</a></p><p>次はT1、T1′、T2′、Mの順に並べた実測結果です。各行はコミットID、親のID、ルートtreeのIDの順です。Mの行には親が二つあるので、IDが一つ多く並びます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git show --no-patch &#39;--format=%h %p %t&#39; &#39;topic~1&#39; &#39;rebased~1&#39; rebased merged</span></span>
<span class="line"><span>887cbcd 89b71e0 b878b3e</span></span>
<span class="line"><span>15dcdfb 1523c8d f19a852</span></span>
<span class="line"><span>3ec0e69 15dcdfb 3512673</span></span>
<span class="line"><span>822401e 1523c8d 22e6717 3512673</span></span></code></pre></div><h2 id="同じファイルに着地しても、親は違う" tabindex="-1">同じファイルに着地しても、親は違う <a class="header-anchor" href="#同じファイルに着地しても、親は違う" aria-label="Permalink to &quot;同じファイルに着地しても、親は違う&quot;">​</a></h2><p>独立した検証リポジトリでは、MとT2′のファイルはどちらも <code>stage.txt</code> が <code>stage=2</code>、<code>enemy.txt</code> が <code>hp=20</code>、<code>spawn.txt</code> が <code>count=3</code> でした。ルートtreeのIDも一致し、二つのコミットを比較する <code>git diff</code> には差分がありませんでした。Mの親はUとT2、T2′の親はT1′です。tree IDがそろっても、コミットの親と履歴は別々に確認できます。<a href="https://git-scm.com/docs/git-diff#_description" target="_blank" rel="noreferrer">Gitの <code>git diff</code> マニュアル</a> · <a href="https://git-scm.com/book/en/v2/Git-Branching-Rebasing#_rebasing" target="_blank" rel="noreferrer">Pro Gitのrebaseの解説</a></p><p>ここでは、互いに別のファイルへの単純な変更を使っています。変更が重なると、rebaseは途中のコミットを再適用する時点で止まることがあります。上流との重複や再適用後に空になる変更の扱いも、rebaseのオプションなどによって変わります。<a href="https://git-scm.com/docs/git-rebase/2.39.0#_options" target="_blank" rel="noreferrer">Git 2.39のrebaseマニュアル</a></p><h2 id="共有済みの履歴に積んだ作業はどこに残るか" tabindex="-1">共有済みの履歴に積んだ作業はどこに残るか <a class="header-anchor" href="#共有済みの履歴に積んだ作業はどこに残るか" aria-label="Permalink to &quot;共有済みの履歴に積んだ作業はどこに残るか&quot;">​</a></h2><p>同僚が元のT2を取得して、その上にCを作ったとします。その後、共有ブランチがT2′を指すように更新されても、Cの親はT2です。新しい先端と同僚の作業は別々の系列に分かれます。</p>`,10)),(t(),i(l,null,{default:a(()=>[c(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20%E5%85%B1%E6%9C%89%E3%83%96%E3%83%A9%E3%83%B3%E3%83%81%E3%81%AE%E6%9B%B4%E6%96%B0%E5%BE%8C%E3%82%82%E5%90%8C%E5%83%9A%E3%81%AE%E4%BD%9C%E6%A5%AD%E3%81%AF%E6%97%A7%E5%B1%A5%E6%AD%B4%E3%81%AB%E6%AE%8B%E3%82%8B%0A%20%20%20%20accDescr%3A%20B%E3%81%8B%E3%82%89T1%E3%80%81T2%E3%80%81%E5%90%8C%E5%83%9A%E3%81%AEC%E3%81%B8%E7%B6%9A%E3%81%8F%E6%97%A7%E7%B3%BB%E5%88%97%E3%81%A8%E3%80%81B%E3%81%8B%E3%82%89U%E3%80%81T1'%E3%80%81T2'%E3%81%B8%E7%B6%9A%E3%81%8F%E6%96%B0%E7%B3%BB%E5%88%97%E3%81%AB%E5%88%86%E3%81%8B%E3%82%8C%E3%82%8B%E3%80%82%0A%20%20%20%20base%5B%22B%20%E5%85%B1%E9%80%9A%E3%81%AE%E5%9F%BA%E6%BA%96%22%5D%20--%3E%20a%5B%22T1%22%5D%20--%3E%20b%5B%22T2%20%E6%97%A7%E5%85%88%E7%AB%AF%22%5D%20--%3E%20peer%5B%22C%20%E5%90%8C%E5%83%9A%E3%81%AE%E4%BD%9C%E6%A5%AD%22%5D%0A%20%20%20%20base%20--%3E%20u%5B%22U%20main%22%5D%20--%3E%20x%5B%22T1%E2%80%B2%22%5D%20--%3E%20y%5B%22T2%E2%80%B2%20%E6%96%B0%E5%85%88%E7%AB%AF%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p>検証では共有をローカルの別ブランチで再現しました。T2はCの祖先ですが、T2′の祖先には含まれず、CとT2′のマージベースはBでした。古い系列をそのまま新しい系列へマージすると、再適用前と再適用後の両方のコミットが履歴に入る場合があります。共有済みの先端を置き換えるときは、その上に積まれた作業の扱いを共同作業者とそろえる必要があります。<a href="https://git-scm.com/book/en/v2/Git-Branching-Rebasing#_rebase_peril" target="_blank" rel="noreferrer">Pro Gitの共有済み履歴のrebase</a> · <a href="https://git-scm.com/docs/git-rebase/2.39.0#_recovering_from_upstream_rebase" target="_blank" rel="noreferrer">Gitの上流rebase後の復旧に関する解説</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>mergeとrebaseの最終treeが一致したら、コミットIDも一致する？</summary><p>この例では一致しません。MはUとT2を親に持ち、T2′はT1′を親に持ちます。親IDもコミットオブジェクトの一部です。</p></details><details class="details custom-block"><summary>Cまで作業した同僚は、新しい共有先端を取得すればCの親も自動で変わる？</summary><p>Cは引き続き元のT2を親に持ちます。新しいT2′の上で作業を続けるなら、Cで加えた変更をどう取り込むかを決めます。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日にWindowsのGit 2.39.2.windows.1で、独立したSHA-1リポジトリを使いました。マージは <code>-s ort --no-ff</code>、rebaseは <code>--merge</code> を指定し、二つの直線的なトピックコミットを競合なく再適用しました。競合時、空の変更、マージコミットの再適用、共有リモートの更新は実測範囲外です。<a href="https://git-scm.com/docs/git-rebase/2.39.0" target="_blank" rel="noreferrer">Git 2.39のrebaseマニュアル</a></p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li>rebase前の先端を参照の移動記録からたどり、いつまで探せるかを確認する。<a href="/study/tools/git-reflog.html">Gitのreflog — 履歴から見えなくなったコミットはどこにあるのか</a></li><li>共有済みの変更を打ち消すコミットが、既存の履歴にどうつながるかを読む。<a href="/study/tools/git-revert.html">Gitのrevert — 履歴を消さずに変更を打ち消す仕組み</a></li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — 親IDとtreeがコミットに入る仕組みを読む。</li><li><a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> — 共通祖先と二つの先端を使って結果を作る方法を確認する。</li><li>rebaseの基準に <code>origin/main</code> を選ぶとき、その参照がいつ更新されるかを確かめる。<a href="/study/tools/git-remote-tracking.html">Gitのリモート追跡ブランチ — origin/mainはサーバーそのものではない</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-rebase/2.39.0" target="_blank" rel="noreferrer">Git公式 — git-rebase 2.39</a></li><li><a href="https://git-scm.com/docs/git-commit-tree" target="_blank" rel="noreferrer">Git公式 — git-commit-tree</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Branching-Rebasing" target="_blank" rel="noreferrer">Pro Git — Rebasing</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Internals-Git-Objects#_git_commit_objects" target="_blank" rel="noreferrer">Pro Git — Git Objects</a></li></ul>',10))])}const _=n(b,[["render",m]]);export{T as __pageData,_ as default};
